            found.append((c.coordinate,v))

print('Found year-like values:', found)

# Also search for 'Year' label
found2=[]
for row in wsD.iter_rows(values_only=False):
    for c in row:
        if isinstance(c.value,str) and 'year' in c.value.lower():
            found2.append((c.coordinate,c.value))
print('Found "year" strings:', found2)

